// AccountServiceServer is the server API for AccountService service.
// All implementations must embed UnimplementedAccountServiceServer
// for forward compatibility.
//
// AccountService owns accounts, characters and persistence (PostgreSQL).
type AccountServiceServer interface {
	// AccountLogin validates an account name + password (legacy _MSG_DBAccountLogin).
	AccountLogin(context.Context, *AccountLoginRequest) (*AccountLoginResponse, error)
	// ListCharacters returns the character-selection projection for an account.
	ListCharacters(context.Context, *ListCharactersRequest) (*ListCharactersResponse, error)
	// LoadCharacter loads one character's full state by slot (_MSG_DBCharacterLogin).
	LoadCharacter(context.Context, *LoadCharacterRequest) (*LoadCharacterResponse, error)
	// SaveCharacter persists one character's state (_MSG_DBSaveMob / SavingQuit).
	SaveCharacter(context.Context, *SaveCharacterRequest) (*SaveCharacterResponse, error)
	QuoteKingdomCape(context.Context, *QuoteKingdomCapeRequest) (*QuoteKingdomCapeResponse, error)
	PurchaseKingdomCape(context.Context, *PurchaseKingdomCapeRequest) (*PurchaseKingdomCapeResponse, error)
	// CreateCharacter creates a character in a free slot (_MSG_DBCreateCharacter).
	CreateCharacter(context.Context, *CreateCharacterRequest) (*CreateCharacterResponse, error)
	// CreateArchCharacter creates the ARCH twin in the first free account slot
	// (_MSG_DBCreateArchCharacter).
	CreateArchCharacter(context.Context, *CreateArchCharacterRequest) (*CreateArchCharacterResponse, error)
	// DeleteCharacter deletes a character after password confirmation.
	DeleteCharacter(context.Context, *DeleteCharacterRequest) (*DeleteCharacterResponse, error)
	// SetPin sets (or changes) the account's numeric PIN, stored as an argon2id
	// hash — never plaintext (legacy _MSG_AccountSecure change path).
	SetPin(context.Context, *SetPinRequest) (*SetPinResponse, error)
	// VerifyPin checks a numeric PIN against the stored hash (legacy
	// _MSG_AccountSecure verify path); NOT_SET means the account has no PIN yet.
	VerifyPin(context.Context, *VerifyPinRequest) (*VerifyPinResponse, error)
	// LoadCargo loads the account-shared cargo (warehouse) gold + items. The cargo
	// is owned by the account, not a single character (all 4 chars share it).
	LoadCargo(context.Context, *LoadCargoRequest) (*LoadCargoResponse, error)
	// SaveCargo persists the account-shared cargo gold + items (replace-all).
	SaveCargo(context.Context, *SaveCargoRequest) (*SaveCargoResponse, error)
	// ListPendingDeliveries returns the account's pending item grants from the
	// delivery_queue mailbox (donate web shop, issue #34). tmServer drains them
	// into the account cargo inside its loop at login, then acks the outcome via
	// SaveCargoWithDeliveries.
	ListPendingDeliveries(context.Context, *ListPendingDeliveriesRequest) (*ListPendingDeliveriesResponse, error)
	// SaveCargoWithDeliveries persists the cargo (replace-all, like SaveCargo) and
	// marks the drained mailbox rows delivered/lost in the SAME transaction — the
	// anti-dup boundary for the drain (web-platform-plan.md §mailbox).
	SaveCargoWithDeliveries(context.Context, *SaveCargoWithDeliveriesRequest) (*SaveCargoResponse, error)
	// SetAccountBlocked flips account.is_blocked by account name — the write side of
	// the in-game GM ban/unban command (issue #122). Login already rejects blocked
	// accounts (LOGIN_RESULT_BLOCKED), so a ban denies re-login immediately and an
	// unban restores it. Administrative-ban ownership may later move to binServer
	// entitlement (web-platform-plan.md §binServer); until then this is the gate.
	SetAccountBlocked(context.Context, *SetAccountBlockedRequest) (*SetAccountBlockedResponse, error)
	// RecordDuelResult persists a 1v1 duel outcome (issue #118, _MSG_ReqRanking):
	// winner_name's wins and loser_name's losses are each incremented by one in
	// character_pvp_stats. Both names must resolve to an existing character or
	// the whole call fails (no lopsided half-result).
	RecordDuelResult(context.Context, *RecordDuelResultRequest) (*RecordDuelResultResponse, error)
	// Guild lifecycle and war/city state (issue #114). These RPCs are modern
	// tmServer↔dbServer calls replacing the legacy DBSrv CPSock relays for
	// GuildInfo, GuildAlly, War, Guilds.txt, Chall_*, and Guild_* files.
	CreateGuild(context.Context, *CreateGuildRequest) (*CreateGuildResponse, error)
	SetGuildMember(context.Context, *SetGuildMemberRequest) (*SetGuildMemberResponse, error)
	LeaveGuild(context.Context, *LeaveGuildRequest) (*SetGuildMemberResponse, error)
	PromoteGuildMember(context.Context, *PromoteGuildMemberRequest) (*PromoteGuildMemberResponse, error)
	TransferGuildLeader(context.Context, *TransferGuildLeaderRequest) (*SetGuildMemberResponse, error)
	SetGuildRelation(context.Context, *SetGuildRelationRequest) (*SetGuildRelationResponse, error)
	ListGuilds(context.Context, *ListGuildsRequest) (*ListGuildsResponse, error)
	ListGuildRelations(context.Context, *ListGuildRelationsRequest) (*ListGuildRelationsResponse, error)
	LoadGuildZones(context.Context, *LoadGuildZonesRequest) (*LoadGuildZonesResponse, error)
	SaveGuildZone(context.Context, *SaveGuildZoneRequest) (*SaveGuildZoneResponse, error)
	LoadGuildTowerState(context.Context, *LoadGuildTowerStateRequest) (*LoadGuildTowerStateResponse, error)
	SaveGuildTowerState(context.Context, *SaveGuildTowerStateRequest) (*SaveGuildTowerStateResponse, error)
	LoadCastleQuestState(context.Context, *LoadCastleQuestStateRequest) (*LoadCastleQuestStateResponse, error)
	SaveCastleQuestState(context.Context, *SaveCastleQuestStateRequest) (*SaveCastleQuestStateResponse, error)
	LoadKefraState(context.Context, *LoadKefraStateRequest) (*LoadKefraStateResponse, error)
	SaveKefraState(context.Context, *SaveKefraStateRequest) (*SaveKefraStateResponse, error)
	mustEmbedUnimplementedAccountServiceServer()
}

